head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.param2 = "";
scwin.param3 = "";
scwin.cnt = 0;
scwin.prevRow = -1;

// 종목기준명 등록 호출

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        ins_combo_set(dts_Cod, "ULDINS91200.xml", SCREN_PROCS_TP_CD_01, "03478", "SEL"); // 03478 - ELS DLS 구분  ELS_DLS_TP_CD  2013.11.25 ELSDLS구분코드 변경
        txb_BAS_ISU_NM.hide();
        btn_search.hide();
        const sd = $c.frame.path("../").scwin.vScrenID;
        if (sd === "ULDINS10100.gfm" || sd === "ULDINS10900.gfm" || sd === "ULDINS15100.gfm" || sd === "ULDINS16200.gfm" ||
            sd === "ULDINS10800.gfm" || sd === "ULDINS16100.gfm") {
            // 채권 접수 , 채권관리 , CP전자단기사채 접수 ,  CP전자단기사채 관리
            // CD 접수,관리
            cmb_ELS_DLS_TP_CD.hide();
            label_8.hide();
            $c.cm.setColumnProp(grd_Grid, "ELS_DLS_NM", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "BAS_ISU_NM", "width", "200");
            scwin.param3 = "0";
        } else if (sd === "ULDINS10200.gfm" || sd === "ULDINS15200.gfm") {
            const ELS_DLS_TP_CD = $c.frame.path("../").cmb_ELS_DLS_TP_CD.getValue();
            // alert(ELS_DLS_TP_CD);
            // elsdls 접수 , 관리
            cmb_ELS_DLS_TP_CD.show("");
            label_8.show("");
            $c.cm.setColumnProp(grd_Grid, "ELS_DLS_NM", "Show", true);
            scwin.param3 = "1";
        }
        const arrPar = new Array();
        const parentWin = $c.frame.path("../");
        const fn_GetPar = parentWin.fn_GetParam;
        if (fn_GetPar !== undefined) {
            fn_GetPar(arrPar);
            scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
            scwin.param2 = ((arrPar.length >= 1) && (arrPar[1] !== undefined) ? arrPar[1] : "");
        }
        // alert(param2);
        await scwin.ins_search(scwin.param1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount === 0) {
            fn_CtrlBtn("no_data");
        } else {
            cmb_ELS_DLS_TP_CD.setValue(dts_List.getCellData(dts_List.getRowPosition(), "ELS_DLS_TP_CD"));
        }
        scwin.cnt = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
        scwin.cnt = 0;
        fn_CtrlBtn("no_data");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91200.dts_List_OnLoadError" });
    }
};

/**
 * @method
