 */
scwin.dts_Cod_OnLoadCompleted = function(rowcount) {
    // alert('dts_Cod.OnLoadCompleted('+rowcount+')');

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        const BAS_ISU_NM = dts_List.getCellData(row, "BAS_ISU_NM");
        const BAS_ISU_ABBRV = dts_List.getCellData(row, "BAS_ISU_ABBRV");
        const BAS_ISU_ENG_NM = dts_List.getCellData(row, "BAS_ISU_ENG_NM");
        const BAS_ISU_ENG_ABBRV = dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV");
        $c.frame.path("../").ins_popupRtn_val4(BAS_ISU_NM, BAS_ISU_ABBRV, BAS_ISU_ENG_NM, BAS_ISU_ENG_ABBRV);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91200.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_new_onclick = function() {
    try {
        scwin.new();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_new_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        dts_List.undoRow(scwin.prevRow);
        scwin.prevRow = row;
        fn_CtrlBtn("update");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name btn_isunm_confirm_onclick
 * @description 「주권종목명확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_isunm_confirm_onclick = function() {
    try {
        ins_popupOpen("", "", "ULDINS90600", "주권 종목코드", "730", "505");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_isunm_confirm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 종목기준명 조회하기 .
 * @param {*} isurcd isurcd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function(isurcd) {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_process
 * @description 종목기준명 저장 , 수정하기   . screenProcsTpCd 02,03
 * @param {String} screenProcsTpCd screenProcsTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_process = async function(screenProcsTpCd) {
    // alert("dts_Out.Text " +dts_Out.Text);
    // alert("dts_Out.ISUR_CD " +dts_Out.NameValue(dts_Out.RowPosition,"ISUR_NM"));
    if (scwin.cnt === 0) {
        // fn_SetHeader() ;

    } else {
        if (!$c.cp.isModified(dts_List)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
    }
    if (txb_NEW_BAS_ISU_NM.getValue() === "" || txb_NEW_BAS_ISU_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준명"));
        txb_NEW_BAS_ISU_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_NEW_BAS_ISU_NM, 60, "한글기준명")) {
        txb_NEW_BAS_ISU_NM.focus();
        return false;
    }
    if (txb_BAS_ISU_ABBRV.getValue() === "" || txb_BAS_ISU_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준약명"));
        txb_BAS_ISU_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ABBRV, 20, "한글기준약명")) {
        txb_BAS_ISU_ABBRV.focus();
        return false;
    }
    if (txb_BAS_ISU_ENG_NM.getValue() === "" || txb_BAS_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문기준명"));
        txb_BAS_ISU_ENG_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ENG_NM, 60, "영문기준명")) {
        txb_BAS_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_BAS_ISU_ENG_ABBRV.getValue() === "" || txb_BAS_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문기준약명"));
        txb_BAS_ISU_ENG_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ENG_ABBRV, 20, "영문기준약명")) {
        txb_BAS_ISU_ENG_ABBRV.focus();
        return false;
    }

    // alert(getObjectValue(cmb_ELS_DLS_TP_CD));

    // ELSDLS구분코드 필수
    if (scwin.param3 === "1" && cmb_ELS_DLS_TP_CD.getValue() === "") {
        await $c.win.alert("ELS/DLS, DLS/DLB구분이 선택되지 않았습니다.");
        cmb_ELS_DLS_TP_CD.focus();
        return false;
    }
    if (scwin.cnt === 0) {

    } else {
        if (screenProcsTpCd === "02") {
            // 등록시 중복체크
            if (scwin.dup() === false) {
                await $c.win.alert("한글기준명 중복입니다.");
                return;
            }
        }
    }
    trs_save.KeyName = "toinb_dataid4";
    // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/CmmInfoAction.do",
        ref : "dts_List",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_remove
 * @description 종목기준명 삭제하기   . screenProcsTpCd 04
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_remove = async function() {
    if (dts_List.getRowCount() === 1) {
        await $c.win.alert("정보가 1건입니다. 삭제불가입니다. 수정만 가능합니다.");
        return;
    }
    const rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_ListDelete.insertRow();
        dts_ListDelete.setCellData(1, "ISUR_CD", dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"));
        dts_ListDelete.setCellData(1, "BAS_ISU_NM", dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM"));

        // alert("dts_ListDelete.ISUR_CD "+ dts_ListDelete.NameValue(dts_ListDelete.RowPosition,"ISUR_CD"));

        trs_remove.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_remove",
            action : "/CmmInfoAction.do",
            ref : "dts_ListDelete",
            target : "trs_remove=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name new
 * @description 신규등록을 위한 dataset 세팅
 * @returns {void}
 * @hidden N
 */
scwin.new = function() {
    dts_List.insertRow();
    dts_List.setCellData(dts_List.getRowPosition(), "ISUR_CD", scwin.param1);
    dts_List.setCellData(dts_List.getRowPosition(), "COM_NM", scwin.param2);
    fn_CtrlBtn("insert");
};

/**
 * @method
 * @name dup
 * @description 한글기준명 중복검사
 * @returns {void}
 * @hidden N
 */
scwin.dup = function() {
    let dupcnt = 0;
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        // alert(dts_List.NameString(i, "BAS_ISU_NM") + " " +txb_NEW_BAS_ISU_NM.value);
        if (dts_List.getCellData(i, "BAS_ISU_NM") === txb_NEW_BAS_ISU_NM.getValue()) {
            dupcnt++;
        }
    }
    // alert("dupcnt " +dupcnt);
    if (dupcnt === 0) {
        return true;
    } // 중복아님
    else {
        return false;
    } // 중복

};
